import React, { useState } from 'react'
import { motion } from 'framer-motion'
import { FaExternalLinkAlt, FaGithub } from 'react-icons/fa'

const projects = [
  {
    title: 'AI Travel Planner',
    description: 'Personalized itinerary planner using Streamlit, Gemini API, RapidAPI, and Folium Maps.',
    tags: ['Python', 'AI', 'Streamlit'],
    link: 'https://github.com/Harshwardhan0270/Travel-Planner',
  },
  {
    title: 'Slack Intern Assignment',
    description: 'Slack UI clone built with HTML, CSS, and vanilla JS for a frontend challenge.',
    tags: ['HTML', 'CSS', 'JavaScript'],
    link: 'https://github.com/Harshwardhan0270/slack-intern-assignment',
  },
  {
    title: 'Portfolio Website',
    description: 'Responsive React + Tailwind portfolio to showcase my skills and projects.',
    tags: ['React', 'Tailwind', 'Framer Motion'],
    link: 'https://github.com/Harshwardhan0270',
  },
  {
    title: 'Question Paper Generator',
    description: "Bloom's Taxonomy-based generator and analyzer using Streamlit, Python, and NLP.",
    tags: ['Python', 'NLP', 'Streamlit'],
    link: 'https://github.com/Harshwardhan0270/Question-Paper-Generator',
  },
  {
    title: 'Multilingual Chatbot App',
    description: 'Chatbot for Indian users using Node.js, LangChain, Google Translate API, and WhatsApp Web.',
    tags: ['Node.js', 'LangChain', 'AI'],
    link: 'https://github.com/Harshwardhan0270/Multilingual-Bot',
  },
]

const allTags = ['All', ...new Set(projects.flatMap(p => p.tags))]

const containerVariants = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.1 } },
}

const cardVariants = {
  hidden: { opacity: 0, y: 30 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.5 } },
}

const Projects = ({ darkMode }) => {
  const [activeTag, setActiveTag] = useState('All')

  const filtered = activeTag === 'All'
    ? projects
    : projects.filter(p => p.tags.includes(activeTag))

  return (
    <motion.div
      initial="hidden"
      animate="visible"
      className={`min-h-screen py-24 px-6 md:px-20 transition-colors duration-300 ${
        darkMode ? 'bg-gray-800 text-white' : 'bg-white text-gray-900'
      }`}
    >
      <motion.div
        variants={{ hidden: { opacity: 0, y: 20 }, visible: { opacity: 1, y: 0, transition: { duration: 0.5 } } }}
        className="text-center mb-10"
      >
        <h2 className="text-3xl font-bold underline underline-offset-8 decoration-purple-500 mb-4 font-poppins">
          Projects
        </h2>
        <p className="text-lg max-w-xl mx-auto font-poppins">
          Explore a few of my recent projects that blend frontend, backend, and AI.
        </p>
      </motion.div>

      {/* Filter Tags */}
      <motion.div
        variants={{ hidden: { opacity: 0 }, visible: { opacity: 1, transition: { duration: 0.4, delay: 0.2 } } }}
        className="flex flex-wrap justify-center gap-2 mb-10"
      >
        {allTags.map(tag => (
          <button
            key={tag}
            onClick={() => setActiveTag(tag)}
            className={`px-4 py-1.5 rounded-full text-sm font-semibold font-poppins transition-all duration-200 ${
              activeTag === tag
                ? 'bg-blue-600 text-white shadow-md'
                : darkMode
                ? 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            {tag}
          </button>
        ))}
      </motion.div>

      <motion.div
        key={activeTag}
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="grid sm:grid-cols-2 lg:grid-cols-3 gap-8"
      >
        {filtered.map((project, index) => (
          <motion.div
            key={index}
            variants={cardVariants}
            whileHover={{ scale: 1.03 }}
            className={`group p-6 rounded-2xl shadow-md border flex flex-col justify-between transition duration-300 ${
              darkMode
                ? 'bg-gray-700 border-gray-600 hover:shadow-blue-900/30 hover:shadow-xl'
                : 'bg-gray-50 border-gray-200 hover:shadow-xl'
            }`}
          >
            <div>
              <div className="mb-3 flex items-center justify-between">
                <h3 className="text-lg font-semibold text-blue-500 font-poppins">
                  {project.title}
                </h3>
                <a
                  href={project.link}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={`View ${project.title} on GitHub`}
                  className="text-blue-400 hover:text-blue-600 transition"
                >
                  <FaGithub size={18} />
                </a>
              </div>
              <p className="text-sm font-poppins mb-4">{project.description}</p>
            </div>
            <div className="flex flex-wrap gap-2 mt-auto">
              {project.tags.map(tag => (
                <span
                  key={tag}
                  className={`text-xs px-2 py-0.5 rounded-full font-poppins ${
                    darkMode ? 'bg-gray-600 text-gray-200' : 'bg-blue-100 text-blue-700'
                  }`}
                >
                  {tag}
                </span>
              ))}
            </div>
          </motion.div>
        ))}
      </motion.div>
    </motion.div>
  )
}

export default Projects
